module hamster_path(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] s,\n    input [2:0] t,\n    input [3:0] num_edges,\n    input [2:0] edge_src [0:15],\n    input [2:0] edge_dst [0:15],\n    input [7:0] edge_weight [0:15],\n    output reg [15:0] result,\n    output reg infinite,\n    output reg done\n);\n\nlocalparam [2:0] IDLE           = 3'd0;\nlocalparam [2:0] INIT           = 3'd1;\nlocalparam [2:0] ITERATE        = 3'd2;\nlocalparam [2:0] PROCESS_EDGES  = 3'd3;\nlocalparam [2:0] CHECK_CONVERGE = 3'd4;\nlocalparam [2:0] FINISH         = 3'd5;\n\nreg [2:0] state;\nreg [15:0] dp0 [0:7];\nreg [15:0] dp1 [0:7];\nreg [15:0] next_dp0 [0:7];\nreg [15:0] next_dp1 [0:7];\nreg [3:0] iter_count;\nreg [3:0] edge_counter;\nreg changed;\nreg [2:0] current_edge_src;\nreg [2:0] current_edge_dst;\nreg [7:0] current_edge_weight;\nreg [15:0] candidate;\ninteger i;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        infinite <= 1'b0;\n        result <= 16'd0;\n        for (i = 0; i < 8; i = i + 1) begin\n            dp0[i] <= 16'hFFFF;\n            dp1[i] <= 16'hFFFF;\n            next_dp0[i] <= 16'hFFFF;\n            next_dp1[i] <= 16'hFFFF;\n        end\n        iter_count <= 4'd0;\n        edge_counter <= 4'd0;\n        changed <= 1'b0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                infinite <= 1'b0;\n                if (start) begin\n                    state <= INIT;\n                end\n            end\n\n            INIT: begin\n                for (i = 0; i < 8; i = i + 1) begin\n                    dp0[i] <= (i == t) ? 16'd0 : 16'hFFFF;\n                    dp1[i] <= (i == t) ? 16'd0 : 16'hFFFF;\n                    next_dp0[i] <= (i == t) ? 16'd0 : 16'hFFFF;\n                    next_dp1[i] <= (i == t) ? 16'd0 : 16'hFFFF;\n                end\n                iter_count <= 4'd0;\n                state <= ITERATE;\n            end\n\n            ITERATE: begin\n                if (iter_count >= 4'd16) begin\n                    state <= FINISH;\n                end else begin\n                    iter_count <= iter_count + 4'd1;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        next_dp0[i] <= dp0[i];\n                        next_dp1[i] <= dp1[i];\n                    end\n                    edge_counter <= 4'd0;\n                    changed <= 1'b0;\n                    state <= PROCESS_EDGES;\n                end\n            end\n\n            PROCESS_EDGES: begin\n                if (edge_counter < num_edges) begin\n                    current_edge_src = edge_src[edge_counter];\n                    current_edge_dst = edge_dst[edge_counter];\n                    current_edge_weight = edge_weight[edge_counter];\n                    candidate = {8'd0, current_edge_weight} +\n                        (current_edge_src[0] ? dp0[current_edge_dst] : dp1[current_edge_dst]);\n\n                    if (current_edge_src[0] == 1'b0) begin\n                        if (candidate > next_dp0[current_edge_src]) begin\n                            next_dp0[current_edge_src] <= candidate;\n                            changed <= 1'b1;\n                        end\n                    end else begin\n                        if (candidate < next_dp1[current_edge_src]) begin\n                            next_dp1[current_edge_src] <= candidate;\n                            changed <= 1'b1;\n                        end\n                    end\n                    edge_counter <= edge_counter + 4'd1;\n                end else begin\n                    state <= CHECK_CONVERGE;\n                end\n            end\n\n            CHECK_CONVERGE: begin\n                if (changed) begin\n                    for (i = 0; i < 8; i = i + 1) begin\n                        dp0[i] <= next_dp0[i];\n                        dp1[i] <= next_dp1[i];\n                    end\n                    state <= ITERATE;\n                end else begin\n                    state <= FINISH;\n                end\n            end\n\n            FINISH: begin\n                if (dp0[s] == 16'hFFFF || iter_count >= 4'd16) begin\n                    infinite <= 1'b1;\n                end else begin\n                    infinite <= 1'b0;\n                    result <= dp0[s];\n                end\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule